}

func batchInsertSnapshot(db *sql.DB, s *gdax.Snapshot) (sql.Result, error) {
	parseBidAsk := func(vals []string) (*parsedBidAsk, error) {
		price, err := strconv.ParseFloat(vals[0], 64)
		if err != nil {
