package main

import (
	"fmt"
	"io"
	"net"

	"github.com/golang/protobuf/proto"

	"github.com/ethanent/gochat/pcol"
	"github.com/ethanent/protostream"
)

type Session struct {
	name   *string
	conn   net.Conn
	stream *protostream.Stream
}

var sessions []Session = []Session{}

func hostServer() {
	ln, err := net.Listen("tcp", ":8080")

	if err != nil {
		panic(err)
	}

	fmt.Println("> Server listening on :8080")

	for {
		conn, err := ln.Accept()

		if err != nil {
			panic(err)
		}

		go handleConn(conn)
	}
}

func handleConn(conn net.Conn) {
	stream := factory.CreateStream()

	stream.Out(conn)

	session := Session{
		name:   nil,
		conn:   conn,
		stream: stream,
	}

	sessions = append(sessions, session)

	stream.Subscribe(&pcol.RegisterClient{}, func(data proto.Message) {
		parsed := data.(*pcol.RegisterClient)

		session.name = &parsed.Name

		for _, sess := range sessions {
			sess.stream.Push(&pcol.RecvBroadcast{
				Sender:  "Server",
				Message: *session.name + " has entered the chat",
			})
		}

		fmt.Println(parsed.Name, "registered")
	})

	stream.Subscribe(&pcol.SendChat{}, func(data proto.Message) {
		parsed := data.(*pcol.SendChat)

		if session.name == nil {
			stream.Push(&pcol.RecvChat{
				Username: "Server",
				Message:  "Failed to send message. Client has not registered.",
			})
			return
		}

		if len(parsed.Message) < 1 {
			stream.Push(&pcol.RecvBroadcast{
				Sender:  "Server",
				Message: "Please type a message.",
			})
			return
		}

		fmt.Println(*session.name, ":", parsed.Message)

		// Broadcast message

		for _, sess := range sessions {
			sess.stream.Push(&pcol.RecvChat{
				Username: *session.name,
				Message:  parsed.Message,
			})
		}
	})

	// Start copying conn data to stream

	_, err := io.Copy(stream, conn)

	// Conn ended probably

	fmt.Println("Terminating conn", err)

	conn.Close()

	// Remove session from list

	for i, sess := range sessions {
		if sess == session {
			sessions = append(sessions[0:i], sessions[i+1:]...)
			fmt.Println("Session dropped successfully!")
			return
		}
	}

	fmt.Println("Session drop failed. Did not locate session.")
}

package main

import (
	"bufio"
	"bytes"
	"crypto/sha1"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net"
)

const (
	EXIT_COMMAND = "exit"
)

// Read message from a net.Conn
func Read(conn net.Conn) (string, error) {
	reader := bufio.NewReader(conn)
	var buffer bytes.Buffer
	for {
		ba, isPrefix, err := reader.ReadLine()
		if err != nil {
			// if the error is an End Of File this is still good
			if err == io.EOF {
				break
			}
			return "", err
		}
		buffer.Write(ba)
		if !isPrefix {
			break
		}
	}
	return buffer.String(), nil
}

// Write message to a net.Conn
// Return the number of bytes returned
func Write(conn net.Conn, encoded string) (int, error) {
	writer := bufio.NewWriter(conn)
	number, err := writer.WriteString(encoded)
	if err == nil {
		err = writer.Flush()
	}
	return number, err
}

// SHA1 hashes using sha1 algorithm
func SHA1(text string) string {
	algorithm := sha1.New()
	algorithm.Write([]byte(text))
	return hex.EncodeToString(algorithm.Sum(nil))
}

func handle(conn net.Conn) {
	defer conn.Close()
	log.Printf("Now listnen: %s \n", conn.RemoteAddr().String())
	content, err := Read(conn)
	if err != nil {
		log.Printf("Listener: Read error: %s", err)
	}
	if content == EXIT_COMMAND {
		log.Println("Listener: Exit!")
		return
	}
	log.Printf("Listener: Received content: %s\n", content)
	response := fmt.Sprintf("Encoded: %s \n", SHA1(content))
	log.Printf("Listener: Response: %s\n", response)
	num, err := Write(conn, response)
	if err != nil {
		log.Printf("Listener: Write Error: %s\n", err)
	}
	log.Printf("Listener: Wrote %d byte(s) to %s \n", num, conn.RemoteAddr().String())
}

func main() {
	listener, err := net.Listen("tcp", ":8080")
	if err != nil {
		// Use fatal to exit if the listener fails to start
		log.Fatal(err)
	}
	defer listener.Close()

	for {
		conn, err := listener.Accept()
		if err != nil {
			// Print the error using a log.Fatal would exit the server
			log.Println(err)
		}
		// Using a go routine to handle the connection
		go handle(conn)
	}
}

package main

import (
	"flag"
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"runtime"
	"runtime/debug"
	"runtime/pprof"
	"syscall"
	"time"

	"github.com/zeldovich/go-rpcgen/rfc1057"
	"github.com/zeldovich/go-rpcgen/xdr"

	"github.com/mit-pdos/go-journal/util"
	"github.com/mit-pdos/go-nfsd/nfstypes"
	"github.com/mit-pdos/go-nfsd/util/timed_disk"

	"github.com/mit-pdos/daisy-nfsd/nfsd"

	"github.com/tchajed/goose/machine/disk"
)

func pmap_set_unset(prog, vers, port uint32, setit bool) bool {
	var cred rfc1057.Opaque_auth
	cred.Flavor = rfc1057.AUTH_NONE

	pmapc, err := net.Dial("tcp", fmt.Sprintf("localhost:%d", rfc1057.PMAP_PORT))
	if err != nil {
		panic(err)
	}
	defer pmapc.Close()
	pmap := rfc1057.MakeClient(pmapc, rfc1057.PMAP_PROG, rfc1057.PMAP_VERS)

	arg := rfc1057.Mapping{
		Prog: prog,
		Vers: vers,
		Prot: rfc1057.IPPROTO_TCP,
		Port: port,
	}

	var res xdr.Bool
	var proc uint32
	if setit {
		proc = rfc1057.PMAPPROC_SET
	} else {
		proc = rfc1057.PMAPPROC_UNSET
	}

	err = pmap.Call(proc, cred, cred, &arg, &res)
	if err != nil {
		panic(err)
	}

	return bool(res)
}

func reportStats(stats []nfsd.OpCount) {
	for _, opCount := range stats {
		op := opCount.Op
		count := opCount.Count
		timeNanos := opCount.TimeNanos
		microsPerOp := float64(timeNanos) / 1e3 / float64(count)
		if count > 0 {
			fmt.Fprintf(os.Stderr,
				"%14s %5d  avg: %0.1f\n",
				op, count, microsPerOp)
		}
	}
}

func logBuildInfo() {
	buildInfo, ok := debug.ReadBuildInfo()
	if !ok {
		log.Printf("Failed to read build info")
		return
	}
	log.Printf("BuildInfo: Main: %+v", buildInfo.Main)
	for _, depmod := range buildInfo.Deps {
		log.Printf("BuildInfo: Dependency: %+v", depmod)
		if depmod.Replace != nil {
			log.Printf("BuildInfo: ---> replaced with: %+v", *depmod.Replace)
		}
	}
}

func main() {
	cpuprofile := flag.String("cpuprofile", "", "write cpu profile to file")
	memprofile := flag.String("memprofile", "", "write mem profile to file")
	mutexprofile := flag.String("mutexprofile", "", "write mutex profile to file")
	blockprofile := flag.String("blockprofile", "", "write block profile to file")

	var diskfile string
	flag.StringVar(&diskfile, "disk", "", "file to store disk in (empty uses MemDisk)")

	var filesizeMegabytes uint64
	flag.Uint64Var(&filesizeMegabytes, "size", 400, "size of file system (in MB)")

	var recover bool
	flag.BoolVar(&recover, "recover", false, "run recovery (rather than initialization)")

	var dumpStats bool
	flag.BoolVar(&dumpStats, "stats", false, "dump stats to stderr on exit")

	var printBuildInfo bool
	flag.BoolVar(&printBuildInfo, "build-info", false, "log build info")
	flag.Uint64Var(&util.Debug, "debug", 0, "debug level (higher is more verbose)")

	flag.Parse()

	if printBuildInfo {
		logBuildInfo()
	}

	// some extra space to hold the log and file-system metadata
	// (this is in blocks, so it only adds 4MB per 1000 blocks)
	diskBlocks := 1500 + filesizeMegabytes*1024/4

	if *cpuprofile != "" {
		f, err := os.Create(*cpuprofile)
		if err != nil {
			log.Fatal(err)
		}
		pprof.StartCPUProfile(f)
		defer pprof.StopCPUProfile()
	}

	if *memprofile != "" {
		f, err := os.Create(*memprofile)
		if err != nil {
			log.Fatal("could not create memory profile: ", err)
		}
		defer f.Close() // error handling omitted for example
		runtime.GC()    // get up-to-date statistics
		if err := pprof.WriteHeapProfile(f); err != nil {
			log.Fatal("could not write memory profile: ", err)
		}
	}
	if *mutexprofile != "" {
		f, err := os.Create(*mutexprofile)
		if err != nil {
			log.Fatal("could not create mutex profile: ", err)
		}
		runtime.SetMutexProfileFraction(1)
		defer func() {
			mp := pprof.Lookup("mutex")
			if mp != nil {
				mp.WriteTo(f, 0)
			}
			f.Close()
		}()
	}
	if *blockprofile != "" {
		f, err := os.Create(*blockprofile)
		if err != nil {
			log.Fatal("could not create block profile: ", err)
		}
		runtime.SetBlockProfileRate(1)
		defer func() {
			mp := pprof.Lookup("block")
			if mp != nil {
				mp.WriteTo(f, 0)
			}
			f.Close()
		}()
	}

	listener, err := net.Listen("tcp", ":0")
	if err != nil {
		panic(err)
	}
	port := uint32(listener.Addr().(*net.TCPAddr).Port)

	pmap_set_unset(nfstypes.MOUNT_PROGRAM, nfstypes.MOUNT_V3, 0, false)
	ok := pmap_set_unset(nfstypes.MOUNT_PROGRAM, nfstypes.MOUNT_V3, port, true)
	if !ok {
		panic("Could not set pmap mapping for mount")
	}
	defer pmap_set_unset(nfstypes.MOUNT_PROGRAM, nfstypes.MOUNT_V3, port, false)

	pmap_set_unset(nfstypes.NFS_PROGRAM, nfstypes.NFS_V3, 0, false)
	ok = pmap_set_unset(nfstypes.NFS_PROGRAM, nfstypes.NFS_V3, port, true)
	if !ok {
		panic("Could not set pmap mapping for NFS")
	}
	defer pmap_set_unset(nfstypes.NFS_PROGRAM, nfstypes.NFS_V3, port, false)

	var d disk.Disk
	if diskfile == "" {
		d = disk.NewMemDisk(diskBlocks)
	} else {
		var err error
		d, err = disk.NewFileDisk(diskfile, diskBlocks)
		if err != nil {
			panic("could not create disk file: " + err.Error())
		}
	}
	if dumpStats {
		d = timed_disk.New(d)
	}
	var nfs *nfsd.Nfs
	if recover {
		if diskfile == "" {
			panic("cannot recover from MemDisk")
		}
		start := time.Now()
		nfs = nfsd.RecoverNfs(d)
		dur := time.Since(start).Truncate(10 * time.Millisecond)
		util.DPrintf(1, "recovered daisy-nfsd from disk in %v", dur)
	} else {
		nfs = nfsd.MakeNfs(d)
	}
	if nfs == nil {
		panic("could not initialize nfs")
	}

	srv := rfc1057.MakeServer()
	srv.RegisterMany(nfstypes.MOUNT_PROGRAM_MOUNT_V3_regs(nfs))
	srv.RegisterMany(nfstypes.NFS_PROGRAM_NFS_V3_regs(nfs))

	sigs := make(chan os.Signal, 1)
	signal.Notify(sigs, os.Interrupt)
	go func() {
		<-sigs
		listener.Close()
		if dumpStats {
			fmt.Fprintf(os.Stderr, "\n")
			opCounts := nfs.GetOpStats()
			reportStats(opCounts)
			d.(*timed_disk.Disk).WriteStats(os.Stderr)
		}
	}()
	if dumpStats {
		usrSig := make(chan os.Signal, 1)
		signal.Notify(usrSig, syscall.SIGUSR1)
		go func() {
			for {
				<-usrSig
				opCounts := nfs.GetOpStats()
				nfs.ResetStats()
				reportStats(opCounts)
				d := d.(*timed_disk.Disk)
				d.WriteStats(os.Stderr)
				d.ResetStats()
			}
		}()
	}

	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Printf("accept: %v\n", err)
			break
		}

		go srv.Run(conn)
	}
}

package main

import (
	"fmt"
	"net"
	"os"
	"path/filepath"	
	"strings"
	"io"
	"bufio"
)
var (
	SPLIT 	= "|"
	W_CMD_I = "w_i"   		//协商写服务器 c->s
	W_CMD_N = []byte("w_n") //请求下一行 s->c
	W_CMD_C = "w_c"			//写服务器结束 c->s
	R_CMD_I = "r_i"			//协商读服务器 c->s
	R_CMD_N = "r_n"			//请求读下一行 c->s
	R_CMD_C = []byte("r_c")	//读服务器结束 s->c
	ERR_CMD = []byte("err_cmd")
	fileName string
)

func init() {
	fileName = getCurrentDirectory()+"/aoki_sp.data"
}

// HandleError 错误处理
func HandleError(err error) {
	fmt.Println("occurred error:", err)
    panic("error.........")
}

//获取当前路径
func getCurrentDirectory() string {
	dir, err := filepath.Abs(filepath.Dir(os.Args[0]))
	if err != nil {
		HandleError(err)
	}
	return strings.Replace(dir, "\\", "/", -1)
}

func writeFile(data []string) {
	file,err := os.Create(fileName)
	defer file.Close()
	if err != nil {
		HandleError(err)
	}
	for _, line := range data {
		file.WriteString(line)
	}
}

func readFile() []string {
	data := make([]string, 0)
	file, err := os.Open(fileName)
	defer file.Close()
	if err != nil {
		HandleError(err)
	}
	buf := bufio.NewReader(file)
	for {
		line, err := buf.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				break
			}
			HandleError(err)
		}		
		data = append(data,line)		
	}	
	return data
}

func writeCmd(conn net.Conn) {
	data := make([]string,1)
	buf := make([]byte, 1024)
	for {
		c, err := conn.Write(W_CMD_N)
		if err != nil {
			HandleError(err)
		}
		// println("write server, send W_CMD_N")
		c, err = conn.Read(buf)
		if err != nil {
			HandleError(err)
		}
		line := string(buf[:c])		
		// println("line=",line)
		if line == W_CMD_C {			
			break
		}
		data = append(data, line)		
	}
	writeFile(data)
	println("write success.")
}

func readCmd(conn net.Conn) {
	data := readFile()
	buf := make([]byte, 16)
	for _, line := range data {
		if line == "" {
			println("line is nil")
			continue
		}
		c, err := conn.Write([]byte(line))
		if err != nil {
			HandleError(err)
		}
		c, err = conn.Read(buf)
		if err != nil {
			HandleError(err)
		}
		cmd := string(buf[:c])
		if cmd != R_CMD_N {
			println("read server,cmd error! cmd=", cmd)
			return
		}
	}
	println("read success.")
	_, err := conn.Write(R_CMD_C)
	if err != nil {
		HandleError(err)
	}
}

