func handleConn(conn net.Conn) {
	println("run handleConn .......")
	defer conn.Close()
	buf := make([]byte, 8)
	c, err := conn.Read(buf)
	if err != nil {
		HandleError(err)
	}

	cmd := string(buf[:c])
	if cmd == W_CMD_I {
		writeCmd(conn)
	} else if cmd == R_CMD_I {
		readCmd(conn)
	} else {
		conn.Write(ERR_CMD)
	}
}

