	"net"

	"github.com/andrewostroumov/go-diameter/v4/diam"
	"github.com/andrewostroumov/go-diameter/v4/diam/dict"
)

func main() {
	dict.Default.LoadFile("diam_app.xml")
	srv, err := net.Listen("tcp", ":3868")
	if err != nil {
		panic(err)
	}
	for {
		if conn, err := srv.Accept(); err != nil {
			panic(err)
		} else {
			go handleClient(conn)
		}
	}
}

func handleClient(conn net.Conn) {
	defer conn.Close()
	for {
		m, err := diam.ReadMessage(conn, dict.Default)
		if err != nil {
			log.Fatal(err)
		}
		log.Println(m)
	}
}

