    h := md5.New()
    h.Write([]byte(str))
    return hex.EncodeToString(h.Sum(nil))
}

func createUser(c *gin.Context)  {
    phone := c.PostForm("phone")
    name := c.PostForm("name")
    user := User {
        Phone: phone,
        Name: name,
        Password: <PASSWORD>("<PASSWORD>"),
    }
    db.Save(&user)
    c.JSON(
