		member.Password = <PASSWORD>
		member.Role = conf.MemberGeneralRole
		member.Avatar = conf.GetDefaultAvatar()
		member.CreateAt = 0
		member.Email = req.Email
		member.Status = 0
		if len(req.Avatar) > 0 {
			member.Avatar = req.Avatar
