func (data *UserData) initUserInfo(model *Model) (error) {
	userID, err := model.mongoDBNextSeq("users")

	if err != nil {
		log.Debug("get next users id error: %v", err)
		return fmt.Errorf("get next users id error: %v", err)
	}

	data.UserID = userID
