package views

import (
	"errors"
	"fmt"
	"log"
	"reflect"
	"strings"
	"text/template"

	"code.minty.io/dingo"
)

var (
	viewCol = make(map[string]View)
)

// View wraps a template and provides CRUD operations, and nesting of templates.
type View interface {
	Name() string
	Associate(names ...string) error
	Associations() []View
	Extends(name string) error
	Extensions() []View
	Data(ctx dingo.Context) []byte
	Reload(ctx dingo.Context) error
	Save(ctx dingo.Context, data []byte) error
	Execute(ctx dingo.Context, data interface{}) error
}

// Add adds a new view to the internal views collection.
func Add(key string, v View) {
	viewCol[key] = v
}

// Get finds a view by it's key.
func Get(key string) View {
	if v, ok := viewCol[key]; ok {
		return v
	}
	return nil
}

// Execute invokes a view by key.
func Execute(ctx dingo.Context, key string, data interface{}) {
	if v, ok := viewCol[key]; !ok {
		ctx.HttpError(404)
	} else if err := v.Execute(ctx, data); err != nil {
		// TODO log this somewhere
		log.Println("dingo: template execution error, ", err)
		/* This will cause a warning to be logged from `net/http/server.go`.
		 * The headers have, most likely, been written to the stream. The error is
		 * occuring midway through template processing, which is writing to the response stream.
		 * Server.go logs this; if we don't call the error handler below, then the stream is cut-off
		 * with no other warning to the client, with this they at-least get the 500 template.
		 */
		ctx.HttpError(500)
	}
}

// CoreView is the most base view, implementing basic functionality.
type CoreView struct {
	IsStale              bool
	ViewName             string
	Associated, Extended []string
}

// Name returns the views name.
func (v *CoreView) Name() string {
	return v.ViewName
}

// Associate relates the given view names with this view.
func (v *CoreView) Associate(names ...string) error {
	for _, n := range names {
		if view := Get(n); view != nil {
			v.Associated = append(v.Associated, view.Name())
		}
	}

	// TODO return an error
	return nil
}

// Associations returns this views associated views.
func (v *CoreView) Associations() (views []View) {
	for _, n := range v.Associated {
		views = append(views, Get(n))
	}
	return
}

// Extend creates a parent/child relationship with the given view name.
func (v *CoreView) Extends(name string) error {
	if view := Get(name); view != nil {
		v.IsStale = true
		v.Extended = append(v.Extended, view.Name())
		view.Associate(v.Name())
	}

	// TODO return an error
	return nil
}

// Extensions returns the list of extended views.
func (v *CoreView) Extensions() (views []View) {
	for _, n := range v.Extended {
		views = append(views, Get(n))
	}
	return
}

/*----------------------------Common Templ Helpers----------------------------*/
func equals(x, y interface{}) bool {
	return x == y
}
func empty(o interface{}) bool {
	switch t := reflect.ValueOf(o); t.Kind() {
	case reflect.Array, reflect.Slice, reflect.Map:
		return t.Len() == 0
	case reflect.String:
		return t.String() == ""
	}
	return true
}

var commonFuncs = template.FuncMap{
	"equals": equals,
	"join":   strings.Join,
	"empty":  empty,
}

// NewTmpl returns a new template
func NewTmpl(name string) *template.Template {
	return template.New(name).Funcs(commonFuncs)
}

// AddTmplFunc adds a function to the templates functions.
func AddTmplFunc(name string, fn interface{}) {
	commonFuncs[name] = fn
}

/*------------------Base Template, base on `text/template`--------------------*/

// TemplateData is a func that returns data for a given template used during rendering.
type TemplateData func(ctx dingo.Context, name string) (*template.Template, []byte, error)

// Base template, extends core template.
type TemplateView struct {
	CoreView
	Tmpl     *template.Template
	TmplData TemplateData
	Bytes    []byte
}

// Init initializes the template
func (v *TemplateView) Init(name string, dataFunc TemplateData) {
	v.ViewName = name
	v.Tmpl, _ = NewTmpl(name).Parse(EmptyTmpl)
	v.TmplData = dataFunc
	v.IsStale = true
}

// Data returns the templates raw data, used for both rendering and editing.
func (v *TemplateView) Data(ctx dingo.Context) []byte {
	if v.IsStale {
		t, b, e := v.TmplData(ctx, v.ViewName)
		if e != nil {
			log.Println(e.Error())
			return []byte(e.Error())
		}
		v.Tmpl, v.Bytes = t, b
	}
	return v.Bytes
}
func reload(ctx dingo.Context, t *template.Template, v []View) error {
	for _, view := range v {
		if err := reload(ctx, t, view.Extensions()); err != nil {
			return err
		} else if t, err = t.Parse(string(view.Data(ctx))); err != nil {
			log.Printf("Failed to parse extension: (%s)\n%s\n", view.Name(), err)
		}
	}
	return nil
}

// Reload reloads the template.
func (v *TemplateView) Reload(ctx dingo.Context) error {
	t, b, e := v.TmplData(ctx, v.ViewName)
	if e != nil {
		log.Println(e)
		return e
	}

	var view View
	// reload/re-parse all extensions
	reload(ctx, t, v.Extensions())
	v.Tmpl, v.Bytes = t, b

	// notify all associated templates
	for _, n := range v.Associated {
		if view = Get(n); view == nil {
			return errors.New(fmt.Sprintf("View doesn't exist: %s\n", n))
		}
		view.Reload(ctx)
	}
	v.IsStale = false

	return nil
}

// Execute writes the template to the response using the given data.
func (v *TemplateView) Execute(ctx dingo.Context, data interface{}) error {
	if v.IsStale {
		v.Reload(ctx)
	}

	if v.Tmpl == nil {
		return errors.New("Template is `nil`")
	}

	return v.Tmpl.Execute(ctx.Response, data)
}

package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os"
	"path"
	"path/filepath"
	"strings"
	"text/template"

	clog "github.com/barelyhuman/commitlog/log"
	git "github.com/go-git/go-git/v5"
)

// Repo - construct containing the details of the cloned repo
type Repo struct {
	Name      string `json:"name"`
	Changelog string `json:"changelog"`
}

var templates *template.Template

func main() {

	var err error
	templates, err = parseTemplates()
	if err != nil {
		log.Println("Error parsing templates, starting only API")
	}

	http.HandleFunc("/generate.json", handleGenerateRequest)
	http.HandleFunc("/generate", handleGenerateRequest)
	http.HandleFunc("/", viewPage)
	http.HandleFunc("/about", viewPage)
	fs := http.FileServer(http.Dir("./static"))
	http.Handle("/static/", http.StripPrefix("/static/", fs))

	port := ":3000"
	if os.Getenv("PORT") != "" {
		port = ":" + os.Getenv("PORT")
	}
	fmt.Println("Listening on" + port)
	http.ListenAndServe(port, nil)
}

func parseTemplates() (templates *template.Template, err error) {
	const directory = "templates"
	var allFiles []string

	dirContents, _ := ioutil.ReadDir(directory)
	for _, file := range dirContents {
		filename := file.Name()
		if strings.HasSuffix(filename, ".html") {
			filePath := filepath.Join(directory, filename)
			allFiles = append(allFiles, filePath)
		}
	}

	templates, err = template.New("").ParseFiles(allFiles...)
	return
}

func viewPage(rw http.ResponseWriter, r *http.Request) {
	pathFile := r.URL.Path[len("/"):]
	if pathFile == "" {
		pathFile = "home"
	}

	rw.Header().Set("Content-Type", "text/html")
	rw.Header().Set("Cache-Control", "no-cache")
	if err := templates.ExecuteTemplate(rw, pathFile+"HTML", nil); err != nil {
		http.Error(rw, err.Error(), http.StatusInternalServerError)
	}
}

func handleGenerateRequest(rw http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		viewGeneratePage(rw, r)
		break
	case http.MethodPost:
		generateCommitlog(rw, r)
		break

	default:
		http.Error(rw, fmt.Errorf("Error").Error(), http.StatusNotFound)
		break
	}
}

func generateCommitlog(rw http.ResponseWriter, r *http.Request) {
	r.ParseForm()
	form := r.Form

	urlToClone := form["github-url"][0]

	shortened := urlToClone
	if strings.Contains(urlToClone, "https://github.com/") {
		shortened = urlToClone[len("https://github.com/"):]
	}

	rw.Header().Set("Cache-Control", "no-cache")
	http.Redirect(rw, r, "/generate?repo="+shortened, http.StatusSeeOther)
}

func viewGeneratePage(rw http.ResponseWriter, r *http.Request) {
	repo := Repo{}
	asJSON := false

	queryValues := r.URL.Query()

	if r.URL.Path == "/generate.json" {
		asJSON = true
	}

	if len(queryValues["repo"]) > 0 {
		repo.Name = queryValues["repo"][0]
	} else {
		http.Error(rw, fmt.Errorf("no repo received").Error(), http.StatusInternalServerError)
		return
	}

	if !(strings.Contains(repo.Name, "https:") || strings.Contains(repo.Name, "http:")) {
		repo.Name = "https://github.com/" + repo.Name
	}

	os.RemoveAll(path.Join("tmp", repo.Name));

	_, err := git.PlainClone(path.Join("tmp", repo.Name), false, &git.CloneOptions{
		URL: repo.Name,
	})

	if err != nil {
		if !strings.Contains(err.Error(), "repository already exists") {
			http.Error(rw, err.Error(), http.StatusInternalServerError)
			return
		}
	}

	rw.Header().Set("Cache-Control", "no-cache")

	if _, err := os.Stat(path.Join("tmp", repo.Name)); os.IsNotExist(err) {
		http.Error(rw, fmt.Errorf("Couldn't find repository").Error(), http.StatusInternalServerError)
		return
	}
	var clogError clog.ErrMessage
	repo.Changelog, clogError = clog.CommitLog(path.Join("tmp", repo.Name), "", "", "ci,refactor,docs,fix,feat,test,chore,other", false)

	if clogError.Err != nil {
		http.Error(rw, clogError.Message, http.StatusInternalServerError)
		return
	}

	if asJSON {
		rw.Header().Set("Content-Type", "application/json")
		json.NewEncoder(rw).Encode(repo)
		return
	}

	htmlFile := path.Join("templates", "generate.html")
	tmpl, err := template.ParseFiles(htmlFile)

	if err != nil {
		http.Error(rw, err.Error(), http.StatusInternalServerError)
		return
	}

	if err := tmpl.Execute(rw, repo); err != nil {
		http.Error(rw, err.Error(), http.StatusInternalServerError)
		return
	}
}

